// Base64-encoded reference bot XML (Martingale/Accumulator), with placeholders
// swapped in for the values AI Bot Builder fills per-generation:
// {{SYMBOL}}, {{GROWTH_RATE}}, {{TAKE_PROFIT}}, {{INITIAL_STAKE}},
// {{MARTINGALE_SIZE}}, {{PROFIT_THRESHOLD}}, {{LOSS_THRESHOLD}}
//
// Stored as base64 because the original XML contains literal backtick and
// quote characters inside some Blockly block IDs, which would break a plain
// JS string/template literal.
//
// Plain CommonJS module (require/module.exports) — not TypeScript/ESM —
// so Vercel's Node runtime never has to guess which module system to use.
const TEMPLATE_B64 =
  '';

function fillBotTemplate(params) {
  const xml = Buffer.from(TEMPLATE_B64, 'base64').toString('utf-8');
  return xml
    .replace('{{SYMBOL}}', params.symbol)
    .replace('{{GROWTH_RATE}}', params.growth_rate)
    .replace('{{TAKE_PROFIT}}', String(params.take_profit))
    .replace('{{INITIAL_STAKE}}', String(params.initial_stake))
    .replace('{{MARTINGALE_SIZE}}', String(params.martingale_size))
    .replace('{{PROFIT_THRESHOLD}}', String(params.profit_threshold))
    .replace('{{LOSS_THRESHOLD}}', String(params.loss_threshold));
}

module.exports = { fillBotTemplate, TEMPLATE_B64 };
